  [1307392] = { { "研ぎ車を組み立て、あなたと近くに座っている者が筋力を6得られるようにします。Strength of Earth Totemとは重複しません。\n\n近くにCampfireが必要です。すべてのキャンプ機能はクールダウン$D1を共有します。", "研ぎ車を組み立て、あなたと近くに座っている者が筋力を11得られるようにします。Strength of Earth Totemとは重複しません。\n\n近くにCampfireが必要です。すべてのキャンプ機能はクールダウン$D1を共有します。", "研ぎ車を組み立て、あなたと近くに座っている者が筋力を20得られるようにします。Strength of Earth Totemとは重複しません。\n\n近くにCampfireが必要です。すべてのキャンプ機能はクールダウン$D1を共有します。", "研ぎ車を組み立て、あなたと近くに座っている者が筋力を$N1得られるようにします。Strength of Earth Totemとは重複しません。\n\n近くにCampfireが必要です。すべてのキャンプ機能はクールダウン$D1を共有します。", shape = { "2/1", "2/1", "2/1", "2/1" } }, nil, 0x55128cbb, nil, "um" },
  [1307393] = { "特定の試薬を作れるSpinning Wheelを設置し、Faction Bannerの効果もすべて得られます。近くにCampfireが必要です。\n\nFaction Bannerの上に設置すると置き換えられます。すべての野営設備はクールダウン$D1を共有します。", nil, 0xade015d4, nil, "um" },
  [1307395] = { "特定の試薬を作れるTanning Rackを設置し、Camp Tentの効果もすべて得られます。近くにCampfireが必要です。\n\nCamp Tentの上に設置すると置き換えられます。すべての野営設備はクールダウン$D1を共有します。", nil, 0xb65c0c33, nil, "um" },
  [1307396] = { "Toxin Studyを設置します。治癒のポーションと解毒剤が入っており、First Aid Kitのすべての効果も与えます。近くにCampfireが必要です。\n\nFirst Aid Kitの上に置いて置き換えることができます。\nすべてのキャンプ機能はクールダウン$D1を共有します。", nil, 0x2d70510c, nil, "um" },
  [1307397] = { "罠が$N1個入ったTrapper's Workbenchを設置し、Camp Chairの効果もすべて得られます。近くにCampfireが必要です。\n\nCamp Chairの上に設置すると置き換えられます。\n\nすべての野営設備はクールダウン$D1を共有します。", nil, 0x6a4f5109, nil, "um" },
  [1307400] = { "Wrathがクリティカルになると、対象にかかっているInsect Swarmの効果時間が$N1秒延長されます。Beastsに対しては、さらに$N2秒延長されます。", nil, 0x7161a38a, nil, "um" },
  [1307411] = { "飲んでね。おいしいよ！", "羽のように体が軽く感じます……そして声がとても甲高くなっています！", 0xd0f4ad45, 0xc36d2ff6, "uu" },
  [1307423] = { "Goaz Warderを起動します。", nil, 0x3e261b23, nil, "um" },
  [1307426] = { "Goaz Warderを起動します。", "起動中です。", 0x5cce541e, 0x3cfa7e61, "uu" },
  [1307508] = { "戦闘中に攻撃を受けると、攻撃者に$N1のNatureダメージと$N2のArcaneダメージを与えます。", "攻撃者に$N1のNatureダメージを与えます。", 0x605e5266, 0xecffe814, "uu" },
  [1307509] = { nil, "攻撃者に$N1のArcaneダメージを与えます。", nil, 0x7c47b36a, "mu" },
  [1307519] = { "$D1の間、自然の加護を呼び起こします。最初に近接攻撃を当ててきた敵は、$D2の間Rooted状態になります。", "次にあなたにMeleeダメージを与えた敵を絡め取ります。", 0x79b02591, 0x831fbd93, "uu" },
  [1307520] = { "ターゲットをその場に縛り付け、$D1かけて$N1のNatureダメージを与えます。ダメージによって効果が中断されることがあります。", "根を張られています。$D1ごとに$N1のNatureダメージを受けています。", 0x7630bc67, 0xb6c2d1ea, "uu" },
