  [1307694] = { "[DNT] $D1ごとに最大体力の$N1%のダメージを受けます。ターゲットを死亡させることはありません。\n\nこれはデバッグ用の呪文です。", "[DNT] $D1ごとに最大体力の$N1%のダメージを受けています。", 0xd831b8af, 0xdf751d76, "uu" },
